-- 在原生mysql交互客户端中阅读；文件须为已审核的逻辑备份
SOURCE /backup/library.sql;
SELECT COUNT(*) AS books_count FROM library.books;

-- 前置：服务器books-load.tsv为两行 1<TAB>云 与 2<TAB>海，LF换行
CREATE TABLE books_load(id INT PRIMARY KEY,title VARCHAR(20));
LOAD DATA INFILE '/var/lib/mysql-files/books-load.tsv'
INTO TABLE books_load CHARACTER SET utf8mb4
FIELDS TERMINATED BY '\t' LINES TERMINATED BY '\n' (id,title);
SELECT id,title FROM books_load ORDER BY id;
